from collections import Counter

class Solution:
    def minimumKeypresses(self, s: str) -> int:
        counts = sorted(Counter(s).values(), reverse=True)
        total = 0
        for i, cnt in enumerate(counts):
            cost = (i // 9) + 1
            total += cnt * cost
        return total

class Solution {
public:
    int minimumKeypresses(std::string s) {
        std::vector<int> counts(26, 0);
        for (char c : s) counts[c - 'a']++;
        std::sort(counts.rbegin(), counts.rend());
        int total = 0;
        for (int i = 0; i < 26 && counts[i] > 0; ++i) {
            total += counts[i] * ((i / 9) + 1);
        }
        return total;
    }
};

class Solution {
    public int minimumKeypresses(String s) {
        int[] counts = new int[26];
        for (char c : s.toCharArray()) counts[c - 'a']++;
        java.util.Arrays.sort(counts);
        int total = 0;
        for (int i = 25; i >= 0 && counts[i] > 0; i--) {
            int rank = 25 - i;
            total += counts[i] * ((rank / 9) + 1);
        }
        return total;
    }
}

var minimumKeypresses = function(s) {
    const counts = new Int32Array(26);
    for (let i = 0; i < s.length; i++) {
        counts[s.charCodeAt(i) - 97]++;
    }
    counts.sort();
    counts.reverse();
    let total = 0;
    for (let i = 0; i < 26 && counts[i] > 0; i++) {
        total += counts[i] * (Math.floor(i / 9) + 1);
    }
    return total;
};
